canvas_draw_line(c,l,t,r,t);canvas_draw_line(c,l,t,x+1,m);canvas_draw_line(c,r,t,x+w-2,m);canvas_draw_line(c,x+1,m,x+w-2,m);
for(int j=t+1;j<m;j++){int inset=(m-j)*(w/5)/(m-t);canvas_draw_line(c,x+2+inset,j,x+w-3-inset,j);}
canvas_draw_rbox(c,x,y+h/2,w,h-h/2,2);if(type==3){canvas_draw_frame(c,x+1,y,w-2,h/2+1);canvas_draw_line(c,x+w/2,y,x+w/2,y+h/2);}else if(type==1){canvas_draw_line(c,x,y+h/2-1,x+w-1,y+h/2-1);}
